    "--version",
    "--json",
    "--format",
    "--quiet",
    "--cycles",
    "--budget-usd",
    "--gbrain",
    "--gstack",
    "--gorchestrator",
    "--gmirror",
    "--gtom",
    "--output",
    "--corpus",
    "--against",
